#!/usr/bin/env Rscript
# Uniform minimal covariate sensitivities and paired context contrasts for all fixed axes.
suppressPackageStartupMessages(library(data.table));a<-commandArgs(TRUE);out<-if(length(a))a[1]else'paper19opp-revision2/reconstruction/candidate_validation';set.seed(202611062L);B<-2000L;P<-10000L
long<-fread(file.path(out,'exploratory_all_gene_axis_effects.tsv.gz'));r<-fread(file.path(out,'harmonized_discovery_ranking.tsv'));fitness<-fread(file.path(out,'discovery_generic_essentiality_baseline.tsv'));ae<-fread(file.path(out,'adamson_control_target_expression_harmonized.tsv'));fe<-fread(file.path(out,'frangieh_control_target_expression_harmonized.tsv'));axes<-unique(long$axis)
q2<-function(x)if(sum(is.finite(x))>=100)as.numeric(quantile(x[is.finite(x)],c(.025,.975)))else c(NA_real_,NA_real_)
partial<-function(x,y,C){X<-cbind(1,apply(C,2,rank,ties.method='average'));qx<-qr(X);if(length(x)<=qx$rank+3)return(NA_real_);xx<-qr.resid(qx,rank(x,ties.method='average'));yy<-qr.resid(qx,rank(y,ties.method='average'));if(sd(xx)<1e-10||sd(yy)<1e-10)return(NA_real_);cor(xx,yy)}
rows<-list();loo<-list();contrasts<-list()
for(st in unique(long$study))for(ctx in unique(long[study==st,context])){
 z<-long[study==st&context==ctx];w<-dcast(z,gene+discovery_cells+validation_cells~axis,value.var=c('discovery_effect','external_effect'));w<-merge(w,r[,.(gene,discovery_control_expression)],by='gene',all.x=TRUE);e<-if(st=='Adamson2016')ae else fe[context==ctx];w<-merge(w,e[,.(gene,external_control_expression=control_mean_logcp10k)],by='gene',all.x=TRUE);w<-merge(w,fitness[,.(gene,depmap_generic_essentiality)],by='gene',all.x=TRUE)
 w[,`:=`(log_discovery_cells=log1p(discovery_cells),log_validation_cells=log1p(validation_cells),log_discovery_expression=log1p(discovery_control_expression),log_external_expression=log1p(external_control_expression),discovery_magnitude=sqrt(discovery_effect_apoptosis^2+discovery_effect_proliferation^2+discovery_effect_stress^2),external_magnitude=sqrt(external_effect_apoptosis^2+external_effect_proliferation^2+external_effect_stress^2))]
 models<-list(cell_support=c('log_discovery_cells','log_validation_cells'),target_expression=c('log_discovery_expression','log_external_expression'),generic_proliferation=c('discovery_effect_proliferation','external_effect_proliferation'),generic_E2F=c('discovery_effect_hallmark_E2F_TARGETS','external_effect_hallmark_E2F_TARGETS'),global_three_program_magnitude=c('discovery_magnitude','external_magnitude'),generic_essentiality='depmap_generic_essentiality')
 for(ax in axes){xx<-w[[paste0('discovery_effect_',ax)]];yy<-w[[paste0('external_effect_',ax)]];n<-nrow(w)
  for(i in seq_len(n))loo[[length(loo)+1L]]<-data.table(study=st,context=ctx,axis=ax,excluded_gene=w$gene[i],genes=n-1L,spearman=cor(xx[-i],yy[-i],method='spearman'))
  for(nm in names(models)){
   cc<-as.matrix(w[,models[[nm]],with=FALSE]);keep<-is.finite(xx)&is.finite(yy)&rowSums(!is.finite(cc))==0;v<-xx[keep];y<-yy[keep];C<-cc[keep,,drop=FALSE];n<-length(v);if(n<8)next;pc<-partial(v,y,C);bb<-vapply(seq_len(B),function(b){ii<-sample.int(n,n,replace=TRUE);partial(v[ii],y[ii],C[ii,,drop=FALSE])},numeric(1));qq<-q2(bb);rows[[length(rows)+1L]]<-data.table(study=st,context=ctx,axis=ax,sensitivity=nm,genes=n,raw_same_genes_spearman=cor(v,y,method='spearman'),partial_rank_correlation=pc,conditional_gene_bootstrap_low=qq[1],conditional_gene_bootstrap_high=qq[2],valid_bootstrap_draws=sum(is.finite(bb)),covariates=paste(models[[nm]],collapse=';'))
  }
 }
}
# Paired whole-gene swaps compare correlations directly on exactly the same genes.
f<-long[study=='Frangieh2021'];for(other in c('IFNγ','Co-culture')){
 aa<-f[context=='Control'];bb<-f[context==other];m<-merge(aa,bb,by=c('gene','axis'),suffixes=c('_control','_other'));genes<-sort(unique(m$gene));n<-length(genes);ids<-replicate(B,sample.int(n,n,replace=TRUE),simplify=FALSE);swap<-replicate(P,sample(c(FALSE,TRUE),n,replace=TRUE),simplify=FALSE)
 for(ax in axes){v<-m[axis==ax];setorderv(v,'gene');x<-v$discovery_effect_control;y1<-v$external_effect_control;y2<-v$external_effect_other;rho1<-cor(x,y1,method='spearman');rho2<-cor(x,y2,method='spearman');delta<-rho1-rho2;vb<-vapply(ids,function(ii)cor(x[ii],y1[ii],method='spearman')-cor(x[ii],y2[ii],method='spearman'),numeric(1));qq<-q2(vb);pn<-vapply(swap,function(s){u<-ifelse(s,y2,y1);v<-ifelse(s,y1,y2);cor(x,u,method='spearman')-cor(x,v,method='spearman')},numeric(1));pv<-(1+sum(abs(pn)>=abs(delta)-1e-12))/(1+length(pn));contrasts[[length(contrasts)+1L]]<-data.table(study='Frangieh2021',comparison=paste('Control minus',other),axis=ax,identical_genes=n,rho_control=rho1,rho_other=rho2,delta_rho=delta,conditional_paired_gene_bootstrap_low=qq[1],conditional_paired_gene_bootstrap_high=qq[2],paired_context_swap_p=pv)
 }
}
c<-rbindlist(contrasts);c[,BH_q_all_24:=p.adjust(paired_context_swap_p,'BH')];fwrite(rbindlist(rows),file.path(out,'exploratory_axis_minimal_covariate_sensitivities.tsv'),sep='\t');fwrite(rbindlist(loo),file.path(out,'exploratory_axis_leave_one_gene_out.tsv.gz'),sep='\t');fwrite(c,file.path(out,'exploratory_paired_context_correlation_differences.tsv'),sep='\t');print(c[axis=='hallmark_UNFOLDED_PROTEIN_RESPONSE']);print(rbindlist(rows)[axis=='hallmark_UNFOLDED_PROTEIN_RESPONSE'])
